namespace {
void require(bool value,const char *text){if(!value)throw std::runtime_error(text);}
void okay(OSStatus status,const char *text){if(status){std::cerr<<text<<": "<<status<<'\n';throw std::runtime_error(text);}}
AudioStreamBasicDescription format(UInt32 bits){AudioStreamBasicDescription value{};value.mSampleRate=48000.;value.mFormatID=kAudioFormatLinearPCM;value.mFormatFlags=UInt32(kAudioFormatFlagsNativeFloatPacked)|UInt32(kAudioFormatFlagIsNonInterleaved);value.mBytesPerFrame=value.mBytesPerPacket=bits/8;value.mFramesPerPacket=1;value.mChannelsPerFrame=2;value.mBitsPerChannel=bits;return value;}
CFPropertyListRef save(AudioUnit unit,float expectedLevel=.375f){CFPropertyListRef output=nullptr;UInt32 size=sizeof(output);okay(AudioUnitGetProperty(unit,kAudioUnitProperty_ClassInfo,kAudioUnitScope_Global,0,&output,&size),"selected precision complete state save");require(output&&CFGetTypeID(output)==CFDictionaryGetTypeID(),"typed complete state dictionary");const auto dictionary=static_cast<CFDictionaryRef>(output);const auto processor=CFDictionaryGetValue(dictionary,CFSTR("Processor State"));const auto controller=CFDictionaryGetValue(dictionary,CFSTR("Controller State"));require(processor&&controller&&CFGetTypeID(processor)==CFDataGetTypeID()&&CFEqual(processor,controller),"coherent selected processor/controller state");const auto data=static_cast<CFDataRef>(processor);require(CFDataGetLength(data)==24&&!std::memcmp(CFDataGetBytePtr(data),"RAVETPS\0",8),"exact public Level codec product/count");float level=0.;std::memcpy(&level,CFDataGetBytePtr(data)+20,4);require(level==expectedLevel,"precision-independent complete f32 Level");return output;}
UInt32 offline(AudioUnit unit){UInt32 value=9,size=sizeof(value);okay(AudioUnitGetProperty(unit,kAudioUnitProperty_OfflineRender,kAudioUnitScope_Global,0,&value,&size),"owned offline mode getter");return value;}
void setOffline(AudioUnit unit,UInt32 value){okay(AudioUnitSetProperty(unit,kAudioUnitProperty_OfflineRender,kAudioUnitScope_Global,0,&value,sizeof(value)),"owned selected precision offline mode change");require(offline(unit)==value,"committed offline mode readback");}
template<typename Sample> void render(AudioUnit unit,AudioTimeStamp &time,UInt32 offset=0,float levelAfterEight=.375f){std::array<std::array<Sample,65>,2> samples{};for(auto &channel:samples)channel.fill(Sample(99));struct Lists{UInt32 count;std::array<AudioBuffer,2> channels;}buffers{2,{{{1,64*sizeof(Sample),samples[0].data()},{1,64*sizeof(Sample),samples[1].data()}}}};static_assert(offsetof(Lists,channels)==offsetof(AudioBufferList,mBuffers));AudioUnitRenderActionFlags flags=0;okay(AudioUnitRender(unit,&flags,&time,0,64,reinterpret_cast<AudioBufferList *>(&buffers)),"actual selected precision render");time.mSampleTime+=64;require(samples[0][64]==99&&samples[1][64]==99,"selected precision output backing tails");for(UInt32 i=0;i<64;++i){const auto n=i>=offset?i-offset:0;const auto expected=i<offset?0.:std::sin(6.283185307179586*440./48000.*n)*(n+1)/240.*double(i<8?.375f:levelAfterEight)/16.;require(std::abs(double(samples[0][i])-expected)<(sizeof(Sample)==8?1e-12:1e-8)&&samples[0][i]==samples[1][i],"selected native precision exact fresh voice/rate/f32 Level");}}
void workerInitialize(AudioUnit unit){std::atomic<bool> done{false};OSStatus status=kAudioUnitErr_FailedInitialization;std::thread worker([&]{status=AudioUnitInitialize(unit);done.store(true,std::memory_order_release);});for(uint32_t attempt=0;attempt<500&&!done.load(std::memory_order_acquire);++attempt)CFRunLoopRunInMode(kCFRunLoopDefaultMode,.01,true);if(!done.load(std::memory_order_acquire)){std::cerr<<"worker initialization failed to return with main runloop pumping\n";std::_Exit(1);}worker.join();okay(status,"worker selected64 initialization with main trampoline");}
void contracts(const char *path){auto url=CFURLCreateFromFileSystemRepresentation(nullptr,reinterpret_cast<const UInt8 *>(path),std::strlen(path),true);auto bundle=CFBundleCreate(nullptr,url);CFRelease(url);require(bundle&&CFBundleLoadExecutable(bundle),"load actual selected precision component");const auto factory=reinterpret_cast<AudioComponentFactoryFunction>(CFBundleGetFunctionPointerForName(bundle,CFSTR("AUWrapperFactory")));require(factory,"actual AU factory");AudioComponentDescription description{'aumu','RvPS','Ravt',0,0};const auto component=AudioComponentRegister(&description,CFSTR("RAVET actual precision contracts"),256,factory);require(component,"actual public in-process registration");AudioUnit unit=nullptr;okay(AudioComponentInstanceNew(component,&unit),"actual public instance");auto setFormat=[&](UInt32 bits){const auto value=format(bits);okay(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Output,0,&value,sizeof(value)),"stopped explicit public audio precision negotiation");};UInt32 maximum=512;okay(AudioUnitSetProperty(unit,kAudioUnitProperty_MaximumFramesPerSlice,kAudioUnitScope_Global,0,&maximum,sizeof(maximum)),"bounded selected frames");setFormat(32);okay(AudioUnitInitialize(unit),"default32 public initialization");okay(AudioUnitSetParameter(unit,1,kAudioUnitScope_Global,0,.375f,0),"f32 Level physical intent");okay(MusicDeviceMIDIEvent(unit,0x90,69,127,0),"fresh32 note");AudioTimeStamp time{};time.mFlags=kAudioTimeStampSampleTimeValid;render<float>(unit,time);auto saved32=save(unit);okay(AudioUnitUninitialize(unit),"stop32 before64 negotiation");
    setFormat(64);okay(AudioUnitSetProperty(unit,kAudioUnitProperty_ClassInfo,kAudioUnitScope_Global,0,&saved32,sizeof(saved32)),"explicit same public Level codec32 to64 recall");setOffline(unit,1);workerInitialize(unit);require(offline(unit)==1,"deferred stopped offline mode consumed on64 initialization");okay(MusicDeviceMIDIEvent(unit,0x90,69,127,3),"queued64 note before rejected offline scalar");UInt32 invalid=2;require(AudioUnitSetProperty(unit,kAudioUnitProperty_OfflineRender,kAudioUnitScope_Global,0,&invalid,sizeof(invalid))!=noErr&&offline(unit)==1,"invalid offline scalar before setup/state/queue mutation");render<double>(unit,time,3);
    okay(MusicDeviceMIDIEvent(unit,0x90,69,127,3),"accepted timed64 note before valid mode transition");okay(AudioUnitSetParameter(unit,1,kAudioUnitScope_Global,0,.5f,8),"accepted timed Level before valid mode transition");setOffline(unit,0);render<double>(unit,time,3,.5f);auto retainedIntent=save(unit,.5f);CFRelease(retainedIntent);
    okay(AudioUnitSetParameter(unit,1,kAudioUnitScope_Global,0,.375f,0),"accepted Level restore before offline setup");okay(MusicDeviceMIDIEvent(unit,0x90,69,127,0),"accepted64 note before offline setup");setOffline(unit,1);render<double>(unit,time);
    okay(AudioUnitReset(unit,kAudioUnitScope_Global,0),"reset preserves selected64 setup/Level");okay(MusicDeviceMIDIEvent(unit,0x90,69,127,0),"fresh64 note after reset");render<double>(unit,time);auto saved64=save(unit);okay(AudioUnitUninitialize(unit),"stop64 before32 negotiation");setFormat(32);okay(AudioUnitSetProperty(unit,kAudioUnitProperty_ClassInfo,kAudioUnitScope_Global,0,&saved64,sizeof(saved64)),"explicit same public Level codec64 to32 recall");setOffline(unit,0);okay(AudioUnitInitialize(unit),"reinitialize32 after64 cleanup");okay(MusicDeviceMIDIEvent(unit,0x90,69,127,0),"fresh32 recalled note");render<float>(unit,time);auto final32=save(unit);CFRelease(final32);okay(AudioUnitUninitialize(unit),"final selected precision stop");okay(AudioComponentInstanceDispose(unit),"actual public retirement");CFRelease(saved32);CFRelease(saved64);CFRelease(bundle);
}
}
int main(int argc,char **argv){try{require(argc==2,"actual component path");contracts(argv[1]);std::cout<<"PASS actual public AU32/64 selected render/offline/reset/main trampoline/complete Level recall contracts\n";return 0;}catch(const std::exception &error){std::cerr<<error.what()<<'\n';return 1;}}
